{
  "qid": "t2i-0009-l3-01",
  "sample_id": "0009",
  "gen_prompt": "倾盆大雨中，一只广东醒狮仍在一座中式庭院里向前猛扑，画面定格在这一瞬间。",
  "invocation": "L3",
  "knowledge_dim": "民俗文化 / 非遗传统表演艺术（广东醒狮·南狮）",
  "fidelity_checks": [
    {
      "check": "狮头表面呈现被大雨淋湿的状态：彩绘头面有湿润水光，且水珠挂于或滴落自独角尖端、额角、眼眶下缘等标志性凸起与边缘处",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["1", "2", "3"],
        "derivation_chain": "前提：倾盆大雨中醒狮照常猛扑 → 知识：醒狮头部为硬体装饰彩绘头，额前有独角状突起，面部有大而圆的凸眼与宽大嘴部造型（清单[1][2][3]）→ 视觉结论：雨水打在头面上形成湿润水光，并沿独角尖端、额角、眼眶下缘等凸起与边缘处挂珠滴落"
      },
      "rubric": {
        "tier_0": "狮头表面干燥无任何雨淋痕迹，与大雨前提互不作用；或狮头缺失标志性凸起造型/被其他头型替代，导致滴水落点不成立",
        "tier_1": "狮头表面有湿润反光，但看不到水珠滴落或流动水痕",
        "tier_2": "狮头彩绘面有明显水光，且可见水珠正挂于或滴落自独角尖端、额角、眼眶下缘等标志性凸起与边缘处"
      },
      "variants_used": "无（清单[1][2][3]均无变体；滴水点以『等凸起与边缘处』涵盖合法的造型差异）",
      "visibility_requirement": "狮头为画面主体必然可见；滴水水珠为瞬时细节，若因构图距离不可见，则以头面湿润反光判及格档，不因水珠不可见直接判0",
      "weight": 1.0
    },
    {
      "check": "布制狮被及其流苏/绒毛镶边吸水后呈湿垂状态：成缕、贴伏、下垂，不再干燥蓬松",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["5"],
        "derivation_chain": "前提：倾盆大雨 → 知识：狮身躯干由彩色布制狮被构成，常带流苏或绒毛镶边（清单[5]）→ 视觉结论：织物与镶边吸水后成缕、贴伏、下垂，整体呈被雨打透的湿透垂坠状而非干燥蓬松"
      },
      "rubric": {
        "tier_0": "狮被整体干燥蓬松如常，与倾盆大雨前提明显矛盾",
        "tier_1": "仅局部（如下摆、镶边末端）呈湿态，大部分狮被仍干燥蓬松",
        "tier_2": "狮被与流苏/绒毛镶边大面积成缕贴伏下垂，整体呈现湿透织物的垂坠质感"
      },
      "variants_used": "覆盖清单[5]变体『常带流苏或绒毛镶边』：镶边为流苏或绒毛均按吸水成缕贴伏判读",
      "visibility_requirement": "狮被为躯干主体必然可见；若镶边细节因构图不可见，以狮被整体是否呈湿垂贴体状态判读",
      "weight": 1.0
    },
    {
      "check": "湿狮被贴附在舞狮者身上，透出或勾勒出下方舞狮者的身体轮廓与发力姿态，画面呈现有人舞动而非无人摆设",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["4", "5"],
        "derivation_chain": "前提：倾盆大雨 → 知识：醒狮处于被舞动状态、狮被下方有舞狮者身体（清单[4]），狮被为织物材质（清单[5]）→ 视觉结论：湿织物贴体，透出或勾勒出舞狮者背部、肩臂的轮廓与向前扑进的发力姿态，绝非无人静态陈列"
      },
      "rubric": {
        "tier_0": "狮被下空无一物、呈无人静态摆设感，或狮被僵硬如实心雕塑、无任何人体结构起伏",
        "tier_1": "狮被下隐约有人体起伏轮廓，但姿态含糊、难以判断与猛扑动作的呼应",
        "tier_2": "湿狮被贴体处清晰透出舞狮者的背/肩/臂轮廓，且与向前猛扑的发力姿态一致"
      },
      "variants_used": "无（清单[4][5]本题相关条目无变体）",
      "visibility_requirement": "需狮被躯干段可见；若狮被较厚未明显贴体，则以狮被下缘可见的人体/腿脚结构作为『有人舞动』的判据（与腿脚检查衔接），不因贴体效果弱直接判0",
      "weight": 1.0
    },
    {
      "check": "舞狮者外露的腿脚被雨淋湿：裤脚与鞋面带水光，弓步蹬地/踏地处溅起可见水花",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["4"],
        "derivation_chain": "前提：倾盆大雨、庭院地面湿滑 → 知识：舞动状态下狮被下方可见舞狮者的腿脚（清单[4]）→ 视觉结论：外露的裤脚与鞋面被淋湿带水光，蹬地/踏地的脚部动作在湿地上溅起水花"
      },
      "rubric": {
        "tier_0": "腿脚可见但完全干燥、无任何雨淋痕迹；或腿脚不可见且画面呈无人静态",
        "tier_1": "腿脚可见且湿润带水光，但缺少水花等雨地动态细节",
        "tier_2": "腿脚湿润有水光，且后蹬/踏地处溅起清晰水花"
      },
      "variants_used": "无",
      "visibility_requirement": "腿脚或狮被下缘与地面接触处至少一处可见即可判；若猛扑腾空瞬间两者均不可见，本条按及格档处理，不直接判0",
      "weight": 1.0
    },
    {
      "check": "庭院地面因大雨形成积水，水面倒映出狮身的彩色影像，并出现雨点激起的涟漪",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["5", "6"],
        "derivation_chain": "前提：倾盆大雨持续落在庭院地面 → 知识：狮被为彩色织物、狮头属传统配色体系，狮身色彩鲜明（清单[5][6]）→ 视觉结论：地面形成积水，水面倒映出与狮身一致的彩色影像，并有雨点激起的涟漪"
      },
      "rubric": {
        "tier_0": "地面干燥无积水，或虽有水但完全无倒影、涟漪等雨天特征",
        "tier_1": "地面有积水但无狮身倒影，或倒影颜色与狮身明显不符、混乱失真",
        "tier_2": "地面有明显积水，倒映出与狮身一致的彩色影像，且可见雨点激起的涟漪"
      },
      "variants_used": "覆盖清单[6]全部变体（刘备狮黄/关公狮红/张飞狮黑/其他传统配色）：倒影颜色随所画狮色判读，不锁定具体色相",
      "visibility_requirement": "需画面包含可见地面；若构图取近景无地面入画，本条按及格档处理，不判0",
      "weight": 1.0
    },
    {
      "check": "画面主体必须是装饰化、夸张彩绘的醒狮头道具形态；全画不得出现真实生物学形态的狮子充当或替代醒狮",
      "anchor": {
        "type": "combination",
        "constraint_refs": ["1", "7"],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "主体被画成真实生物学形态的狮子（写实狮类动物），或画面中出现真实狮子替代/混入醒狮",
        "tier_1": "主体为狮形但装饰化特征不全：头部接近写实动物形态、缺少彩绘与装饰结构，介于动物与道具之间",
        "tier_2": "主体为明确的装饰化、夸张彩绘醒狮头道具形态，全画面无任何真实生物学狮子"
      },
      "variants_used": "无",
      "visibility_requirement": "全画面范围判读，主体必然可见",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "题面规定『一只广东醒狮』：画面中醒狮数量为一只",
      "facet": "quantity",
      "rubric": {
        "tier_0": "无醒狮，或出现两只及以上完整醒狮",
        "tier_1": "主体为一只，但画面边缘出现其他醒狮局部/残影造成数量歧义",
        "tier_2": "全画面恰有一只醒狮主体"
      }
    },
    {
      "check": "题面点名『广东醒狮』为主体：醒狮占据画面主导地位",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "醒狮缺失，或仅为画面边缘的小元素",
        "tier_1": "醒狮可见但体量偏小、不构成视觉焦点",
        "tier_2": "醒狮为画面最大、最醒目的主体，位于视觉中心区域"
      }
    },
    {
      "check": "题面规定『倾盆大雨的中式庭院』：场景为中式庭院且大雨正在落下",
      "facet": "real_world_scene",
      "rubric": {
        "tier_0": "场景既非中式庭院也无降雨（如干燥的现代室内）",
        "tier_1": "中式庭院与明显降雨仅满足其一（如有庭院但无雨幕，或有雨但场景非中式庭院）",
        "tier_2": "中式庭院背景清晰可辨，且雨幕/雨丝/雨点明显可见"
      }
    },
    {
      "check": "题面规定『向前猛扑的瞬间』：醒狮整体呈现向前猛扑的动态",
      "facet": "fullbody_action",
      "rubric": {
        "tier_0": "醒狮呈静止直立/摆拍姿态，与猛扑无关",
        "tier_1": "有前倾或移动趋势，但动感不足、姿态含糊",
        "tier_2": "头部前探、躯干前倾、四肢呈弓步/蹬地发力，整体呈现明确的向前猛扑动势"
      }
    }
  ],
  "quality_facets": ["physical_logic", "material_texture", "edge_clarity"],
  "aesthetic_facets": ["composition", "color_harmony", "lighting_atmosphere", "anatomical_fidelity"],
  "leak_check": {
    "对照表": [
      {"constraint_ref": "1", "题面中是否出现": "无"},
      {"constraint_ref": "2", "题面中是否出现": "无"},
      {"constraint_ref": "3", "题面中是否出现": "无"},
      {"constraint_ref": "4", "题面中是否出现": "无"},
      {"constraint_ref": "5", "题面中是否出现": "无"},
      {"constraint_ref": "6", "题面中是否出现": "无"},
      {"constraint_ref": "7", "题面中是否出现": "无"}
    ],
    "结论": "全为无"
  },
  "notes": "本题以『倾盆大雨中照常猛扑』为反事实式前提（常规大雨会停演，题面设定演出继续），所有雨效结论（头面挂珠、狮被湿垂成缕、湿布贴体透出人体、腿脚水花、地面倒影）均为推导结论、未写入题面。『猛扑』仅为动作前提，用于保证清单[4]舞动状态可判，未泄漏『腿脚可见』等检查点；题面未指定狮头配色与视角，清单[6]全部变体均合法，各检查已附最低可见条件与不可见时处置。"
}
